<style>
    [data-contact-type] button { border: 1px solid var(--border); background: transparent; color: inherit; cursor: pointer; }
    [data-contact-type] button:hover { border-color: var(--primary); }
    [data-contact-type] button[aria-pressed="true"] {
        border-color: var(--primary) !important;
        background: var(--primary) !important;
        color: var(--primary-foreground) !important;
    }
</style>
<script>
    (() => {
        const wrap = document.querySelector("[data-contact-type]");
        if (!wrap) return;
        const input = wrap.parentElement.querySelector('input[name="customer_type"]');
        wrap.querySelectorAll("button[data-type]").forEach((btn) => {
            btn.addEventListener("click", () => {
                wrap.querySelectorAll("button[data-type]").forEach((item) => {
                    item.setAttribute("aria-pressed", item === btn ? "true" : "false");
                });
                if (input) input.value = btn.dataset.type;
            });
        });
    })();
</script>
